// Per-page dictionaries.
//
// Pages other than the home page keep their strings in
// `app/i18n/pages/<page>/en.ts` (English source of truth) plus one partial
// `<locale>.json` per translated locale. Keeping them out of the global
// dictionary means each page only ships its own strings to the client.
//
// Each page folder's `index.ts` is generated by `scripts/gen-page-dicts.mjs`
// (run it after adding or removing a locale JSON).

import { deepMerge } from "./dictionaries";
import { DEFAULT_LOCALE } from "./config";

/** Build a `(locale) => strings` loader; missing keys fall back to English. */
export function makePageDict<T>(
  en: T,
  partials: Record<string, unknown>
): (locale: string) => T {
  return (locale: string) => {
    if (locale === DEFAULT_LOCALE) return en;
    const partial = partials[locale];
    return partial ? deepMerge(en, partial) : en;
  };
}
